//! The comparison table: Run Comparison's metric-by-method table, which every single-method run
//! that prints rho/Gamma/sojourn/E[·] rows also uses.
//!
//! In 0.90.34 this was an awk program generated by `buildComparisonAwk` in QnetGUIApp.swift and
//! run by BWK `/usr/bin/awk` over each method's output file (the `-G`/`-c` compact format the
//! solvers print: `rho_1 = 0.686014	(0.002761)`) and, for a tractable network, over
//! `BNET_analytical_<pid>.txt`, the editor's tractability means written by `writeAnalyticalFile`
//! at %.17g. `singleMethodFormatCmd` called it with one column. Under D1 there is no awk at run
//! time (RUN-066, Changed): [`comparison_table`] reads the same text and returns the same bytes,
//! and [`analytical_file`] writes the same hand-over text, so the parsing, the rounding (`fmt7`,
//! `fmtv`), the widths and the blank lines are 0.90.34's. `tests/output_table.rs` runs the awk
//! programs found in the golden wrappers (and ones generated by the Swift itself) as the oracle.
//!
//! Faithful to awk on purpose, because the bytes depend on it (see `awk.rs`): a value is the
//! solver's own spelling until `fmt7` reads it with C's `strtod`, so `nan` and `inf` print as C
//! prints them and a NaN compares equal to everything, as in BWK's `relop`; a computed −0 is 0;
//! the file counter only advances on a file's first record, so an empty file shifts the columns
//! after it, as it did; widths count bytes except that `—` counts one and `±` one.

use std::collections::HashMap;

use super::awk::rel;
use crate::cfmt;
use crate::traffic::SrbmData;

/// The variable name of the queue-length rows: E[X_k] for finite buffers, E[Q_k] for infinite.
#[derive(Debug, Clone, Copy, PartialEq, Eq)]
pub enum VarName {
    X,
    Q,
}

impl VarName {
    pub fn as_str(self) -> &'static str {
        match self {
            VarName::X => "X",
            VarName::Q => "Q",
        }
    }

    /// The variable for a network's buffer mode.
    pub fn for_buffers(infinite: bool) -> Self {
        if infinite {
            VarName::Q
        } else {
            VarName::X
        }
    }
}

/// One method column: its header label and the text its solver printed (the whole output file).
#[derive(Debug, Clone)]
pub struct MethodColumn {
    pub label: String,
    pub output: String,
}

/// Everything `buildComparisonAwk` was given.
#[derive(Debug, Clone)]
pub struct TableSpec {
    /// The method columns in order; Run Comparison puts the simulation last, as the reference.
    pub columns: Vec<MethodColumn>,
    pub var_name: VarName,
    pub show_gamma: bool,
    pub show_sojourn: bool,
    pub show_xclass: bool,
    /// The analytical hand-over text ([`analytical_file`]), when the network is tractable.
    pub analytical: Option<String>,
    /// The analytical column's header (the editor's tractability means label); blank means
    /// "Exact Result".
    pub analytical_label: Option<String>,
    /// Whether the analytical values are exact (then they are every row's reference) or
    /// asymptotic (then the last method is).
    pub analytical_is_exact: bool,
    /// Adds "Average of Algorithms" when there are at least three method columns.
    pub show_average: bool,
    /// Settings ▸ Output Format ▸ Output decimals (clamped to 0…9).
    pub decimals: i64,
}

impl TableSpec {
    /// A single-method run's table (`singleMethodFormatCmd`): one column, Gamma and sojourn rows
    /// shown, no class rows, no average.
    pub fn single(label: &str, output: &str, var_name: VarName, analytical: Option<String>, analytical_label: Option<String>, analytical_is_exact: bool, decimals: i64) -> Self {
        TableSpec {
            columns: vec![MethodColumn { label: label.into(), output: output.into() }],
            var_name,
            show_gamma: true,
            show_sojourn: true,
            show_xclass: false,
            analytical,
            analytical_label,
            analytical_is_exact,
            show_average: false,
            decimals,
        }
    }
}

/// The analytical hand-over file `writeAnalyticalFile` wrote (`BNET_analytical_<pid>.txt`), or None
/// when it wrote none (the network is not tractable or has no means). `data` is the station model
/// for the network's own buffer mode; when it is missing or its dimension differs from the means,
/// only the E[·] lines are written, as 0.90.34 did.
pub fn analytical_file(tractable: bool, means: &[f64], data: Option<&SrbmData>, var_name: VarName) -> Option<String> {
    if !tractable || means.is_empty() {
        return None;
    }
    let mut lines = Vec::new();
    if let Some(data) = data.filter(|d| d.d == means.len()) {
        for k in 0..data.d {
            let rho = if data.capacity[k] > 1e-12 { data.alpha[k] / data.capacity[k] } else { 0.0 };
            lines.push(format!("rho_{} = {}", k + 1, cfmt::f("%.17g", rho)));
        }
        for k in 0..data.d {
            lines.push(format!("Gamma_{} = {}", k + 1, cfmt::f("%.17g", data.alpha[k])));
        }
        for k in 0..data.d {
            let g = data.alpha[k];
            let soj = if g > 1e-12 { means[k] / g } else { 0.0 };
            lines.push(format!("sojourn_{} = {}", k + 1, cfmt::f("%.17g", soj)));
        }
    }
    for (i, m) in means.iter().enumerate() {
        lines.push(format!("E[{}_{}] = {}", var_name.as_str(), i + 1, cfmt::f("%.17g", *m)));
    }
    Some(lines.join("\n") + "\n")
}

/// C's `atof`, which BWK awk used for a string's numeric value (see [`super::awk::number`]).
pub fn awk_number(s: &str) -> f64 {
    super::awk::number(s)
}

/// The table's number rule (`fmt7`): `decimals` fraction digits, scientific with max(1, D − 1)
/// mantissa digits when 0 < |x| < 10^−D (never at D = 0) or |x| ≥ 1e9, and a signed zero shown
/// unsigned. The display filter applies the same rule, so it leaves a table unchanged.
pub fn fmt7(x: f64, decimals: i64) -> String {
    let d = decimals.clamp(0, 9);
    let sci = if d < 2 { 1 } else { d - 1 };
    let smallest: f64 = if d == 0 { 0.0 } else { format!("1e-{d}").parse().unwrap() };
    let a = if rel(x, 0.0) < 0 { -x } else { x };
    let s = if rel(x, 0.0) != 0 && (rel(a, smallest) < 0 || rel(a, 1e9) >= 0) {
        cfmt::f(&format!("%.{sci}e"), x)
    } else {
        cfmt::f(&format!("%.{d}f"), x)
    };
    nz(s)
}

/// awk `nz`: `/^-0(\.0*)?$/` loses its sign.
fn nz(s: String) -> String {
    if let Some(rest) = s.strip_prefix('-') {
        if rest == "0" || (rest.starts_with("0.") && rest[2..].bytes().all(|b| b == b'0')) {
            return rest.to_string();
        }
    }
    s
}

/// An awk value as these programs use one: a string from a field, or a number computed in END.
#[derive(Debug, Clone)]
enum Val {
    Str(String),
    Num(f64),
}

impl Val {
    fn is_empty(&self) -> bool {
        matches!(self, Val::Str(s) if s.is_empty())
    }
    fn num(&self) -> f64 {
        match self {
            Val::Str(s) => awk_number(s),
            Val::Num(x) => *x,
        }
    }
}

/// awk `fmt7(v)`: the empty string and the em-dash pass through.
fn fmt7_val(v: &Val, decimals: i64) -> String {
    if let Val::Str(s) = v {
        if s.is_empty() || s == "—" {
            return s.clone();
        }
    }
    fmt7(v.num(), decimals)
}

/// awk `fmtv(v, ref, ci)`: "value ± half (+x.x%)", "—" for an empty value; the percent is taken on
/// the values as displayed and dropped when there is no reference or it displays as zero.
fn fmtv(v: &Val, r: &Val, ci: &str, decimals: i64) -> String {
    if v.is_empty() {
        return "—".into();
    }
    let mut s = fmt7_val(v, decimals);
    if !ci.is_empty() {
        s = format!("{s} ± {}", fmt7_val(&Val::Str(ci.into()), decimals));
    }
    if r.is_empty() || rel(r.num(), 0.0) == 0 {
        return s;
    }
    let vr = awk_number(&fmt7_val(v, decimals));
    let rr = awk_number(&fmt7_val(r, decimals));
    if rel(rr, 0.0) == 0 {
        return s;
    }
    // BWK awk stores a computed -0 as 0 (`setfval`), so equal values show (+0.0%).
    let pct = (vr - rr) / rr * 100.0;
    format!("{s} ({}%)", cfmt::f("%+.1f", if pct == 0.0 { 0.0 } else { pct }))
}

/// awk `dwid`: bytes, with each `—` counted once and each `±` once.
fn dwid(s: &str) -> usize {
    s.len() - 2 * s.matches('—').count() - s.matches('±').count()
}

/// awk `idxw`: the digits of a station index.
fn idxw(n: u64) -> usize {
    n.to_string().len()
}

/// The five metric arrays of one file, keyed by station index.
#[derive(Debug, Default)]
struct Metric {
    v: HashMap<(usize, u64), String>,
    ci: HashMap<(usize, u64), String>,
}

impl Metric {
    fn get(&self, f: usize, k: u64) -> Val {
        Val::Str(self.v.get(&(f, k)).cloned().unwrap_or_default())
    }
    fn ci(&self, f: usize, k: u64) -> String {
        self.ci.get(&(f, k)).cloned().unwrap_or_default()
    }
}

/// BWK awk's default field splitting: runs of blanks, tabs and newlines.
fn fields(rec: &str) -> Vec<&str> {
    rec.split([' ', '\t', '\n']).filter(|s| !s.is_empty()).collect()
}

/// `s=$n; gsub(/[^0-9]/,"",s); k=s+0`.
fn index_of(field: &str) -> u64 {
    let digits: String = field.chars().filter(|c| c.is_ascii_digit()).collect();
    awk_number(&digits) as u64
}

/// awk records of one file: split on newline; a last line without one still counts.
fn records(text: &str) -> Vec<&str> {
    let mut v: Vec<&str> = text.split('\n').collect();
    if v.last() == Some(&"") {
        v.pop();
    }
    v
}

/// The table `buildComparisonAwk` printed for `spec`.
pub fn comparison_table(spec: &TableSpec) -> String {
    let n = spec.columns.len();
    let has_an = spec.analytical.is_some();
    let has_avg = spec.show_average && n >= 3;
    let total_files = if has_an { n + 1 } else { n };
    let var = spec.var_name.as_str();
    let dec = spec.decimals;

    // ── the per-record rules ──
    let (mut rh, mut gm, mut sj, mut xc, mut ex) = Default::default();
    let (mut an_rh, mut an_gm, mut an_sj, mut an) =
        (HashMap::<u64, String>::new(), HashMap::<u64, String>::new(), HashMap::<u64, String>::new(), HashMap::<u64, String>::new());
    let (mut dr, mut dg, mut ds, mut dxc, mut dx) = (0u64, 0u64, 0u64, 0u64, 0u64);
    let ex_prefix = format!("E[{var}_");
    let mut f = 0usize;
    let files = spec.columns.iter().map(|c| c.output.as_str()).chain(spec.analytical.as_deref());
    for text in files {
        for (fnr, rec) in records(text).into_iter().enumerate() {
            if fnr == 0 {
                f += 1;
            }
            if rec.starts_with('=') || rec.is_empty() {
                continue;
            }
            let fl = fields(rec);
            let fld = |i: usize| fl.get(i - 1).copied().unwrap_or("");
            let nf = fl.len();
            if f <= n {
                let put = |m: &mut Metric, kf: usize, vf: usize, d: &mut u64| {
                    let k = index_of(fld(kf));
                    m.v.insert((f, k), fld(vf).to_string());
                    if nf > vf && fld(vf + 1).starts_with('(') {
                        m.ci.insert((f, k), fld(vf + 1).replace(['(', ')'], ""));
                    }
                    if k > *d {
                        *d = k;
                    }
                };
                if rec.starts_with("rho_") {
                    put(&mut rh, 1, 3, &mut dr);
                    continue;
                }
                if rec.starts_with("Gamma_") {
                    put(&mut gm, 1, 3, &mut dg);
                    continue;
                }
                if rec.starts_with("sojourn_") {
                    put(&mut sj, 1, 3, &mut ds);
                    continue;
                }
                if rec.starts_with("X(class") {
                    put(&mut xc, 2, 4, &mut dxc);
                    continue;
                }
                if rec.starts_with(&ex_prefix) {
                    put(&mut ex, 1, 3, &mut dx);
                    continue;
                }
            }
            if has_an && f == total_files {
                let put = |m: &mut HashMap<u64, String>, d: &mut u64| {
                    let k = index_of(fld(1));
                    m.insert(k, fld(3).to_string());
                    if k > *d {
                        *d = k;
                    }
                };
                if rec.starts_with("rho_") {
                    put(&mut an_rh, &mut dr);
                } else if rec.starts_with("Gamma_") {
                    put(&mut an_gm, &mut dg);
                } else if rec.starts_with("sojourn_") {
                    put(&mut an_sj, &mut ds);
                } else if rec.starts_with(&ex_prefix) {
                    put(&mut an, &mut dx);
                }
            }
        }
    }
    let (rh, gm, sj, xc, ex): (Metric, Metric, Metric, Metric, Metric) = (rh, gm, sj, xc, ex);

    // ── END ──
    let no_ref = n == 1 && !has_an;
    let use_an_ref = has_an && spec.analytical_is_exact;
    let an_get = |m: &HashMap<u64, String>, k: u64| Val::Str(m.get(&k).cloned().unwrap_or_default());
    let empty = Val::Str(String::new());
    let ncols = n + 1 + usize::from(has_avg) + usize::from(has_an);
    let avg_col = n + 2;
    let an_col = if has_an { if has_avg { n + 3 } else { n + 2 } } else { 0 };

    let mut rows: Vec<(Vec<String>, bool)> = Vec::new();
    let new_row = || vec![String::new(); ncols + 1];

    let mut header = new_row();
    for (i, c) in spec.columns.iter().enumerate() {
        header[i + 2] = c.label.clone();
    }
    if has_avg {
        header[avg_col] = "Average of Algorithms".into();
    }
    if has_an {
        let trimmed = spec.analytical_label.as_deref().unwrap_or("").trim_matches([' ', '\t']);
        header[an_col] = if trimmed.is_empty() { "Exact Result".into() } else { trimmed.to_string() };
    }
    rows.push((header, false));
    let mut rule = new_row();
    for (i, c) in spec.columns.iter().enumerate() {
        rule[i + 2] = "=".repeat(c.label.chars().count());
    }
    if has_avg {
        rule[avg_col] = "=".repeat(21);
    }
    if has_an {
        rule[an_col] = "=".repeat(12);
    }
    rows.push((rule, true));

    enum AnFill<'a> {
        Map(&'a HashMap<u64, String>),
        Dash,
        Plain(&'a HashMap<u64, String>),
    }
    let block = |rows: &mut Vec<(Vec<String>, bool)>, label: &str, dmax: u64, m: &Metric, refv: &dyn Fn(u64) -> Val, fill: AnFill| {
        let w = idxw(dmax);
        for k in 1..=dmax {
            let mut row = new_row();
            row[1] = label.replace("{}", &format!("{k:0w$}"));
            let r = refv(k);
            for i in 1..=n {
                row[i + 1] = fmtv(&m.get(i, k), &r, &m.ci(i, k), dec);
            }
            if has_avg {
                let (mut s, mut c) = (0.0f64, 0u32);
                for i in 1..n {
                    let v = m.get(i, k);
                    if !v.is_empty() {
                        s += v.num();
                        c += 1;
                    }
                }
                row[avg_col] = if c > 0 { fmtv(&Val::Num(s / c as f64), &r, "", dec) } else { "—".into() };
            }
            if has_an {
                row[an_col] = match fill {
                    AnFill::Map(a) => match a.get(&k).filter(|s| !s.is_empty()) {
                        None => "—".into(),
                        Some(s) => fmt7_val(&Val::Str(s.clone()), dec),
                    },
                    AnFill::Dash => "—".into(),
                    AnFill::Plain(a) => fmt7_val(&an_get(a, k), dec),
                };
            }
            rows.push((row, false));
        }
        if dmax > 0 {
            rows.last_mut().unwrap().1 = true;
        }
    };
    let method_ref = |m: &Metric, k: u64| if no_ref { empty.clone() } else { m.get(n, k) };
    let pick = |a: &HashMap<u64, String>, m: &Metric, k: u64| if use_an_ref { an_get(a, k) } else { method_ref(m, k) };

    block(&mut rows, "rho_{}", dr, &rh, &|k| pick(&an_rh, &rh, k), AnFill::Map(&an_rh));
    if spec.show_gamma {
        block(&mut rows, "Gamma_{}", dg, &gm, &|k| pick(&an_gm, &gm, k), AnFill::Map(&an_gm));
    }
    if spec.show_sojourn {
        block(&mut rows, "sojourn_{}", ds, &sj, &|k| pick(&an_sj, &sj, k), AnFill::Map(&an_sj));
    }
    if spec.show_xclass {
        block(&mut rows, "X(class {})", dxc, &xc, &|k| method_ref(&xc, k), AnFill::Dash);
    }
    block(&mut rows, &format!("E[{var}_{{}}]"), dx, &ex, &|k| pick(&an, &ex, k), AnFill::Plain(&an));

    // ── widths and printing ──
    let mut mw = vec![0usize; ncols + 1];
    for (row, _) in &rows {
        for c in 1..=ncols {
            mw[c] = mw[c].max(dwid(&row[c]));
        }
    }
    let mut out = String::new();
    for (row, gap) in &rows {
        for c in 1..=ncols {
            out.push_str(&row[c]);
            if c < ncols {
                let p = mw[c] as isize - dwid(&row[c]) as isize + 2;
                for _ in 0..p.max(0) {
                    out.push(' ');
                }
            }
        }
        out.push('\n');
        if *gap {
            out.push('\n');
        }
    }
    out
}

#[cfg(test)]
mod tests {
    use super::*;

    #[test]
    fn fmt7_follows_the_display_rule() {
        assert_eq!(fmt7(0.70001, 3), "0.700");
        assert_eq!(fmt7(0.0004, 3), "4.00e-04");
        assert_eq!(fmt7(0.0004, 0), "0");
        assert_eq!(fmt7(-0.0, 3), "0.000");
        assert_eq!(fmt7(3.456789e20, 6), "3.45679e+20");
        assert_eq!(fmt7(0.5, 1), "0.5");
        assert_eq!(fmt7(0.04, 1), "4.0e-02");
    }

    #[test]
    fn a_single_column_shows_no_percent_and_pads_indices() {
        let mut out = String::new();
        for k in 1..=10 {
            out.push_str(&format!("rho_{k} = 0.5\nE[Q_{k}] = 1.25\n"));
        }
        let t = comparison_table(&TableSpec::single("QNA", &out, VarName::Q, None, None, true, 3));
        assert!(t.starts_with("         QNA\n         ===\n\nrho_01   0.500\n"), "{t}");
        assert!(t.contains("E[Q_10]  1.250\n\n"), "{t}");
    }
}
